  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B054",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made superconducting artificial atoms and microwave photons a controllable platform for fundamental quantum optics and quantum information. Its conceptual reach and sustained experimental impact are prize-level.",
        "attribution": "Blais supplied the key theoretical architecture; Wallraff and Schoelkopf helped establish and demonstrate the experimental platform. Steven M. Girvin's foundational theoretical contributions make the three-person limit a real attribution difficulty.",
        "maturity": "The field has decades of replication, increasingly sophisticated devices, and results across many laboratories. Its scientific importance stands independently of whether scalable fault-tolerant computers are achieved.",
        "uncertainties": [
          "The discovery spans theory and several experimental groups, so choosing only three risks underrepresenting essential contributions.",
          "The long-term limits and scientific reach of large-scale superconducting processors remain unsettled."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B026",
      "proposed_laureates": [
        "Immanuel Bloch",
        "Markus Greiner",
        "Peter Zoller"
      ],
      "assessment": {
        "nobel_worthiness": "Ultracold atoms in optical lattices turned controlled many-body quantum simulation into an experimental discipline, enabling direct studies of lattice models and emergent phases.",
        "attribution": "Zoller's theoretical vision and the experimental advances of Bloch and Greiner represent complementary parts of the achievement. The credited contributions extend to other major theorists and experimentalists, including Dalibard and Cirac.",
        "maturity": "The platform has produced a sustained body of reproducible results and has been adopted widely. Its value as a controlled setting for many-body physics is already established.",
        "uncertainties": [
          "Some simulated regimes remain difficult to benchmark independently or connect quantitatively to real materials.",
          "The credit is distributed across multiple laboratories and the candidate's five credited names exceed the Nobel limit."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B004",
      "proposed_laureates": [
        "Andrew N. Cleland",
        "Markus Aspelmeyer",
        "Tobias J. Kippenberg"
      ],
      "assessment": {
        "nobel_worthiness": "Cavity optomechanics and quantum acoustics have brought mechanical degrees of freedom into regimes of quantum control, extending quantum optics to mesoscopic motion and creating new tools for sensing and quantum science.",
        "attribution": "Cleland represents quantum acoustic devices, while Aspelmeyer and Kippenberg were central to cavity optomechanics. The shared credit reflects distinct but converging experimental routes.",
        "maturity": "Cooling, state preparation, and coherent control have been demonstrated in multiple systems, with substantial international replication. The central physics is mature even as larger and more useful quantum devices remain a goal.",
        "uncertainties": [
          "The broad description combines related but not identical research programs, making a single discovery boundary difficult to draw.",
          "The extent to which these techniques will enable new tests of quantum mechanics at larger scales remains open."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of time-reversal-invariant topological insulators and the quantum spin Hall effect established a major new class of quantum matter and reshaped condensed-matter physics.",
        "attribution": "Kane and Mele developed the decisive theoretical predictions; Molenkamp's experiments provided an early realization of the quantum spin Hall state. This is a strong theory-experiment pairing.",
        "maturity": "The theoretical framework and experimental identification of topological phases have been tested across material platforms and have generated a durable research area.",
        "uncertainties": [
          "Early material realizations were limited by sample quality and finite-temperature behavior, though later work broadened the evidence."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks transformed precision timekeeping by combining narrow optical transitions with control of systematic shifts, enabling exceptionally accurate measurement and new tests of fundamental physics.",
        "attribution": "Katori's lattice-clock concept and Ye's experimental advances are both central to the field's development. The two-person attribution fits the credited contribution particularly well.",
        "maturity": "Independent groups have realized and compared clocks at extraordinary precision, establishing a robust technology and measurement capability. The scientific value is not dependent on future applications.",
        "uncertainties": [
          "The boundary between the original invention and subsequent advances in clock performance is broad, though the named contributions are well established."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Allan H. MacDonald",
        "Pablo Jarillo-Herrero",
        "Rafi Bistritzer"
      ],
      "assessment": {
        "nobel_worthiness": "Magic-angle twisted bilayer graphene revealed that moiré systems can host narrow bands and strong correlations, opening a flexible experimental route to engineered quantum materials.",
        "attribution": "Bistritzer and MacDonald made the theoretical prediction of magic-angle flat bands; Jarillo-Herrero's experiments revealed correlated insulating and superconducting behavior. The named theory-experiment combination captures the field's catalytic start.",
        "maturity": "The initial results prompted extensive work across materials and devices, but sample dependence, competing phases, and the interpretation of superconductivity remain active questions.",
        "uncertainties": [
          "The degree to which the initial superconducting observations reflect a universal mechanism is unresolved.",
          "It remains uncertain which results in the rapidly evolving moiré field will prove foundational over the long term."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B030",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "The theoretical proposal and experimental realization of trapped-ion quantum computing established a leading platform for coherent control of individual quantum systems and multi-qubit operations.",
        "attribution": "Cirac and Zoller supplied landmark theoretical foundations, while Blatt led decisive experimental demonstrations. Their roles are complementary and closely tied to the discovery described.",
        "maturity": "Ion traps have demonstrated long coherence, high-fidelity operations, and substantial replication across laboratories. The platform's foundational significance is clear even though large-scale error-corrected computing remains incomplete.",
        "uncertainties": [
          "The candidate overlaps substantially with broader quantum-information contributions and with other proposed quantum-computing discoveries.",
          "The practical scaling limits of trapped-ion processors remain under active investigation."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B047",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information could in principle be protected from noise and provided the conceptual basis for fault-tolerant quantum computation. This is a profound contribution to quantum physics and information science.",
        "attribution": "Shor and Steane introduced landmark error-correcting codes, while Kitaev developed influential topological approaches. These are distinct contributions to a broad theoretical foundation.",
        "maturity": "Error correction has moved from theory to repeated experimental demonstrations of logical control and suppression of errors, but scalable fault tolerance has not yet been reached.",
        "uncertainties": [
          "The candidate groups several major ideas developed by different people over time, so its scope and attribution are difficult to delimit.",
          "How soon, or whether, present approaches will yield practical large-scale fault-tolerant machines remains uncertain."
        ]
      }
    }
  ]
}
